module watchdog_timer(  
    input wire clk,  
    input wire reset,  
    input wire watchdog_reset,  
    output reg timeout  
);  
    parameter TIMEOUT_LIMIT = 10; // Arbitrary timeout limit for the watchdog  
    reg [3:0] counter; // 4-bit counter to count clock cycles  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            counter <= 0;  
            timeout <= 0;  
        end else if (watchdog_reset) begin  
            counter <= 0;  
            timeout <= 0;  
        end else begin  
            if (counter < TIMEOUT_LIMIT) begin  
                counter <= counter + 1;  
                timeout <= 0;  
            end else begin  
                timeout <= 1;  
            end  
        end  
    end  
endmodule

