module butterworth_filter (  
    input clk,  // Clock signal  
    input rst,  // Reset signal  
    input signed [15:0] x_in,  // Input sample  
    output reg signed [15:0] y_out  // Filtered output  
);  
    reg signed [15:0] x_mem [0:1];  // Memory for input samples  
    reg signed [15:0] y_mem [0:1];  // Memory for output samples  
    integer i;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            // Reset all registers  
            for (i = 0; i < 2; i = i + 1) begin  
                x_mem[i] <= 0;  
                y_mem[i] <= 0;  
            end  
            y_out <= 0;  
        end else begin  
            // Shift input samples  
            x_mem[1] <= x_mem[0];  
            x_mem[0] <= x_in;  

            // Perform Butterworth filter operation (simplified)  
            y_mem[1] <= y_mem[0];  
            y_mem[0] <= (x_mem[0] + 2*x_mem[1] + y_mem[1]) >> 2;  

            // Output the filtered signal  
            y_out <= y_mem[0];  
        end  
    end  
endmodule

