module viterbi_decoder (
    input clk,
    input reset,
    input [1:0] received_bits, // 2 bits of received data
    output reg [1:0] decoded_bits, // Decoded bits
    output reg valid // Indicates valid output
);
    reg [1:0] state[0:3]; // state storage
    reg [3:0] metric[0:3]; // path metrics
    integer i;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            for (i = 0; i < 4; i = i + 1) begin
                state[i] <= 2'b00;
                metric[i] <= 4'b1111; // maximum value for initialization
            end
