module spi_controller(  
    input clk,  
    input chip_select,  
    input start,  
    input [7:0] mosi,  
    output reg [7:0] miso,  
    output reg ready  
);  

    reg [2:0] bit_count;  
    reg [7:0] data_buffer;  

    always @(posedge clk or negedge chip_select) begin  
        if (!chip_select) begin  
            ready <= 0;  
            bit_count <= 3'b000;  
            data_buffer <= mosi;  
        end else if (start) begin  
            if (bit_count < 8) begin  
                miso[bit_count] <= data_buffer[bit_count];  
                bit_count <= bit_count + 1;  
            end else begin  
                ready <= 1;  
                bit_count <= 3'b000;  
            end  
        end  
    end  
endmodule

