module pll_8x (
    input wire clk_ref,    // Reference clock input
    input wire reset,      // Reset signal
    output reg clk_out     // Output clock
);
    reg [2:0] count;       // 3-bit counter for 8x frequency

    always @(posedge clk_ref or posedge reset) begin
        if (reset) begin
            count <= 3'b0;
            clk_out <= 0;
        end else begin
            if (count == 3'b111) begin
                clk_out <= ~clk_out; // Toggle output clock every 8 counts
                count <= 3'b0;
            end else begin
                count <= count + 1;
            end
        end
    end
endmodule

