module divide_by_4(  
    input clk,  
    input rst,  
    output reg out  
);  
    reg [1:0] counter;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            counter <= 2'b00;  
            out <= 1'b0;  
        end else begin  
            if (counter == 2'b11) begin  
                counter <= 2'b00;  
                out <= ~out;  
            end else begin  
                counter <= counter + 1;  
            end  
        end  
    end  
endmodule

