module vco (
    input wire clk,
    input wire reset,
    input wire [3:0] control_voltage,
    input wire clk_enable,
    output reg vco_out
);

    reg [25:0] counter;
    wire [25:0] frequency;

    // Simple mapping (for example purposes)
    assign frequency = (control_voltage == 4'b0000) ? 26'd1000000 :
                       (control_voltage == 4'b0001) ? 26'd2000000 :
                       (control_voltage == 4'b0010) ? 26'd3000000 :
                       (control_voltage == 4'b0011) ? 26'd4000000 :
                       (control_voltage == 4'b0100) ? 26'd5000000 :
                       26'd1000000; // Default frequency

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 0;
            vco_out <= 0;
        end else if (clk_enable) begin
            if (counter >= frequency) begin
                counter <= 0;
                vco_out <= ~vco_out; // Toggle output
            end else begin
                counter <= counter + 1;
            end
        end
    end
endmodule

