module rsa_encrypt (
    input [15:0] plaintext,
    input [3:0] exponent,
    input [15:0] modulus,
    output reg [15:0] ciphertext,
    input clk,
    input rst
);
    reg [15:0] temp;
    reg [3:0] count;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            ciphertext <= 16'd0;
            temp <= 16'd1;
            count <= 4'd0;
        end else begin
            if (count < exponent) begin
                temp <= (temp * plaintext) % modulus; // Multiplication and mod
                count <= count + 1;
            end else begin
                ciphertext <= temp;
            end
        end
    end
endmodule

