module noise_suppression_filter(  
    input clk,  
    input rst,  
    input signal_in,  
    output reg signal_out  
);  
    parameter STABLE_COUNT = 4;  
    reg [1:0] state;  
    reg [1:0] count;  
    reg last_signal;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            state <= 0;  
            count <= 0;  
            signal_out <= 0;  
            last_signal <= 0;  
        end else begin  
            if (signal_in == last_signal) begin  
