    reg [7:0] dividend;
    reg [7:0] divisor;
    reg reset;
    wire [7:0] quotient;
    wire ready;
    wire [7:0] remainder;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    divider_8bit dut (
        .clk(clk),
        .dividend(dividend),
        .divisor(divisor),
        .reset(reset),
        .quotient(quotient),
        .ready(ready),
        .remainder(remainder)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

        begin
            reset = 1;
            dividend = 0;
            divisor = 0;
            @(posedge clk);
            #2 reset = 0;

            @(posedge clk);
        end
        endtask
    task wait_for_ready;

        begin

            fork : timeout_block
                begin
                    wait(ready == 1'b1);
                end
                begin
                    #2000;
                end
            join_any
            disable timeout_block;

            #1;
        end
        endtask

    task testcase001;

        begin
            test_num = test_num + 1;
            $display("Test Case %0d: Simple Division (10 / 2)", test_num);
            reset_dut();
            dividend = 8'd10;
            divisor = 8'd2;
            wait_for_ready();
            #1;

            check_outputs(8'd5, 1'b1, 8'd0);
        end
        endtask

